// Read-only Detour structural comparison for the single detail-error factor.
#include "DetourNavMesh.h"
#include <fstream>
#include <iostream>
#include <vector>
#include <cstring>
#include <stdexcept>
struct SetHeader {int magic,version,numTiles;dtNavMeshParams params;};
struct TileHeader {dtTileRef ref;int size;};
static size_t align4(size_t n){return (n+3)&~size_t(3);}
struct Mesh {std::vector<unsigned char> raw;SetHeader head;};
Mesh read(const char*path){std::ifstream f(path,std::ios::binary);Mesh m;m.raw.assign(std::istreambuf_iterator<char>(f),{});if(m.raw.size()<sizeof(SetHeader))throw std::runtime_error("short set");std::memcpy(&m.head,m.raw.data(),sizeof(m.head));if(m.head.magic!=('M'<<24|'S'<<16|'E'<<8|'T')||m.head.version!=1)throw std::runtime_error("bad set");return m;}
struct Tile{dtMeshHeader h;dtTileRef ref;std::vector<std::vector<unsigned char>> groups;};
Tile tile(const Mesh&m,size_t&cursor){TileHeader th;if(cursor+sizeof(th)>m.raw.size())throw std::runtime_error("tile header");std::memcpy(&th,m.raw.data()+cursor,sizeof(th));cursor+=sizeof(th);size_t start=cursor;Tile t;t.ref=th.ref;if(th.size<int(sizeof(t.h))||cursor+th.size>m.raw.size())throw std::runtime_error("tile size");std::memcpy(&t.h,m.raw.data()+cursor,sizeof(t.h));if(t.h.magic!=DT_NAVMESH_MAGIC||t.h.version!=DT_NAVMESH_VERSION)throw std::runtime_error("mesh header");cursor+=align4(sizeof(t.h));size_t sizes[]={sizeof(float)*3*t.h.vertCount,sizeof(dtPoly)*t.h.polyCount,sizeof(dtLink)*t.h.maxLinkCount,sizeof(dtPolyDetail)*t.h.detailMeshCount,sizeof(float)*3*t.h.detailVertCount,size_t(4)*t.h.detailTriCount,sizeof(dtBVNode)*t.h.bvNodeCount,sizeof(dtOffMeshConnection)*t.h.offMeshConCount};for(size_t n:sizes){n=align4(n);if(cursor+n>start+th.size)throw std::runtime_error("group size");t.groups.emplace_back(m.raw.begin()+cursor,m.raw.begin()+cursor+n);cursor+=n;}if(cursor!=start+th.size)throw std::runtime_error("tile residual");return t;}
int main(int argc,char**argv){try{if(argc!=3)return 1;Mesh a=read(argv[1]),b=read(argv[2]);bool set=std::memcmp(&a.head,&b.head,sizeof(a.head))==0,headers=true,refs=true;bool groups[8]={true,true,true,true,true,true,true,true};if(a.head.numTiles!=b.head.numTiles)throw std::runtime_error("tile count changed");size_t ac=sizeof(SetHeader),bc=sizeof(SetHeader);int av=0,bv=0,at=0,bt=0,polys=0;for(int i=0;i<a.head.numTiles;++i){Tile x=tile(a,ac),y=tile(b,bc);refs&=x.ref==y.ref;av+=x.h.detailVertCount;bv+=y.h.detailVertCount;at+=x.h.detailTriCount;bt+=y.h.detailTriCount;polys+=x.h.polyCount;x.h.detailVertCount=y.h.detailVertCount=0;x.h.detailTriCount=y.h.detailTriCount=0;headers&=std::memcmp(&x.h,&y.h,sizeof(x.h))==0;for(int k=0;k<8;++k)groups[k]&=x.groups[k]==y.groups[k];}if(ac!=a.raw.size()||bc!=b.raw.size())throw std::runtime_error("set residual");std::cout<<std::boolalpha<<"{\"set_header_identical\":"<<set<<",\"normalized_tile_headers_identical\":"<<headers<<",\"tile_refs_identical\":"<<refs;const char*names[]={"base_vertices","polygons","links","detail_meshes","detail_vertices","detail_triangles","bv_tree","offmesh_connections"};for(int k=0;k<8;++k)std::cout<<",\""<<names[k]<<"_identical\":"<<groups[k];std::cout<<",\"control_detail_vertices\":"<<av<<",\"candidate_detail_vertices\":"<<bv<<",\"control_detail_triangles\":"<<at<<",\"candidate_detail_triangles\":"<<bt<<",\"base_polygons\":"<<polys<<"}\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 2;}}
